<?php
$titulo_pagina='Agenda de estudos'; $css_extra='agenda.css';
require_once '../includes/header.php';
$usuario_id=(int)$_SESSION['usuario_id'];
$pdo->exec("CREATE TABLE IF NOT EXISTS agenda_estudos (
 id INT AUTO_INCREMENT PRIMARY KEY,
 usuario_id INT NOT NULL,
 titulo VARCHAR(120) NOT NULL,
 tema VARCHAR(100) NOT NULL,
 data_estudo DATE NOT NULL,
 hora_inicio TIME NOT NULL DEFAULT '16:00:00',
 duracao_minutos SMALLINT NOT NULL DEFAULT 30,
 observacoes VARCHAR(500) NULL,
 concluido TINYINT(1) NOT NULL DEFAULT 0,
 criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX idx_agenda_usuario_data (usuario_id, data_estudo),
 CONSTRAINT fk_agenda_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$_SESSION['agenda_csrf']??=bin2hex(random_bytes(32));$error='';
$monthInput=(string)($_GET['m']??date('Y-m'));$month=DateTimeImmutable::createFromFormat('!Y-m-d',$monthInput.'-01');
if(!$month||$month->format('Y-m')!==$monthInput)$month=new DateTimeImmutable(date('Y-m-01'));
$monthStart=$month->format('Y-m-01');$monthEnd=$month->modify('last day of this month')->format('Y-m-d');
$requestedDate=(string)($_GET['date']??'');$selectedDate=DateTimeImmutable::createFromFormat('!Y-m-d',$requestedDate);
if(!$selectedDate||$selectedDate->format('Y-m-d')!==$requestedDate||$selectedDate->format('Y-m')!==$month->format('Y-m'))$selectedDate=$month->format('Y-m')===date('Y-m')?new DateTimeImmutable('today'):$month;
$selectedDateString=$selectedDate->format('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['agenda_csrf'],$_POST['csrf'])){$error='A sessão expirou. Atualize a página e tente novamente.';}
 else{
  $action=(string)($_POST['action']??'');
  if($action==='add'){
   $title=trim((string)($_POST['titulo']??''));$topic=trim((string)($_POST['tema']??''));$date=(string)($_POST['data_estudo']??'');$time=(string)($_POST['hora_inicio']??'');$duration=filter_var($_POST['duracao']??30,FILTER_VALIDATE_INT);$notes=trim((string)($_POST['observacoes']??''));
   $validDate=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
   if($title===''||mb_strlen($title)>120||$topic===''||mb_strlen($topic)>100||!$validDate||$validDate->format('Y-m-d')!==$date||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time)||!$duration||$duration<10||$duration>300||mb_strlen($notes)>500){$error='Confira os campos: atividade, tema, data, horário e duração entre 10 e 300 minutos.';}
   else{$stmt=$pdo->prepare('INSERT INTO agenda_estudos (usuario_id,titulo,tema,data_estudo,hora_inicio,duracao_minutos,observacoes) VALUES (:uid,:titulo,:tema,:data,:hora,:duracao,:obs)');$stmt->execute(['uid'=>$usuario_id,'titulo'=>$title,'tema'=>$topic,'data'=>$date,'hora'=>$time.':00','duracao'=>$duration,'obs'=>$notes===''?null:$notes]);$_SESSION['agenda_notice']='Sessão adicionada à sua agenda.';$_SESSION['agenda_csrf']=bin2hex(random_bytes(32));header('Location: agenda.php?m='.$validDate->format('Y-m').'&date='.$date.'#dia-selecionado');exit;}
  }elseif($action==='toggle'||$action==='delete'){
   $eventId=filter_var($_POST['event_id']??null,FILTER_VALIDATE_INT);
   if($eventId){if($action==='toggle'){$stmt=$pdo->prepare('UPDATE agenda_estudos SET concluido=1-concluido WHERE id=:id AND usuario_id=:uid');$stmt->execute(['id'=>$eventId,'uid'=>$usuario_id]);$_SESSION['agenda_notice']='Status da sessão atualizado.';}else{$stmt=$pdo->prepare('DELETE FROM agenda_estudos WHERE id=:id AND usuario_id=:uid');$stmt->execute(['id'=>$eventId,'uid'=>$usuario_id]);$_SESSION['agenda_notice']='Sessão removida da agenda.';}$back=(string)($_POST['data_estudo']??$selectedDateString);$backDate=DateTimeImmutable::createFromFormat('!Y-m-d',$back);if(!$backDate||$backDate->format('Y-m-d')!==$back)$backDate=$selectedDate;$_SESSION['agenda_csrf']=bin2hex(random_bytes(32));header('Location: agenda.php?m='.$backDate->format('Y-m').'&date='.$backDate->format('Y-m-d').'#dia-selecionado');exit;}
   $error='Não foi possível localizar essa sessão.';
  }else{$error='Ação inválida.';}
 }
}
$notice=$_SESSION['agenda_notice']??'';unset($_SESSION['agenda_notice']);
$stmt=$pdo->prepare('SELECT id,titulo,tema,data_estudo,hora_inicio,duracao_minutos,observacoes,concluido FROM agenda_estudos WHERE usuario_id=:uid AND data_estudo BETWEEN :inicio AND :fim ORDER BY data_estudo,hora_inicio,id');$stmt->execute(['uid'=>$usuario_id,'inicio'=>$monthStart,'fim'=>$monthEnd]);$events=$stmt->fetchAll();$byDay=[];foreach($events as $event)$byDay[$event['data_estudo']][]=$event;
$weekday=(int)$month->format('N');$gridStart=$month->modify('-'.($weekday-1).' days');$lastDay=(int)$month->format('t');$gridDays=(int)ceil(($weekday-1+$lastDay)/7)*7;$previous=$month->modify('-1 month');$next=$month->modify('+1 month');$doneCount=count(array_filter($events,static fn($e)=>(int)$e['concluido']===1));$openCount=count($events)-$doneCount;
$weekdays=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];$monthNames=[1=>'janeiro',2=>'fevereiro',3=>'março',4=>'abril',5=>'maio',6=>'junho',7=>'julho',8=>'agosto',9=>'setembro',10=>'outubro',11=>'novembro',12=>'dezembro'];$monthName=$monthNames[(int)$month->format('n')];$monthTitle=$monthName.' '.$month->format('Y');
?>
