 <div class="agenda-layout"><section class="agenda-calendar-card" aria-label="Calendário mensal"><header class="calendar-toolbar"><div><span class="panel-eyebrow">CALENDÁRIO DE ESTUDOS</span><h2><span class="calendar-month-name"><?= escape($monthName) ?></span> <?= $month->format('Y') ?></h2></div><nav aria-label="Navegar meses"><a href="?m=<?= $previous->format('Y-m') ?>" aria-label="Mês anterior">‹</a><a class="calendar-today" href="?m=<?= date('Y-m') ?>&date=<?= date('Y-m-d') ?>">Hoje</a><a href="?m=<?= $next->format('Y-m') ?>" aria-label="Próximo mês">›</a></nav></header>
 <div class="calendar-grid calendar-weekdays"><?php foreach($weekdays as $weekdayName): ?><span><?= $weekdayName ?></span><?php endforeach; ?></div><div class="calendar-grid calendar-days"><?php for($i=0;$i<$gridDays;$i++):$day=$gridStart->modify('+'.$i.' days');$dateKey=$day->format('Y-m-d');$dayEvents=$byDay[$dateKey]??[];$outside=$day->format('m')!==$month->format('m');$today=$dateKey===date('Y-m-d');$selected=$dateKey===$selectedDateString;$url='?m='.$day->format('Y-m').'&date='.$dateKey.'#dia-selecionado'; ?><a class="calendar-day <?= $outside?'outside-month':'' ?> <?= $today?'is-today':'' ?> <?= $selected?'is-selected':'' ?> <?= $dayEvents?'has-events':'' ?>" href="<?= escape($url) ?>" aria-label="<?= $day->format('d/m/Y') ?>, <?= count($dayEvents) ?> sessões"><span class="calendar-day-number"><?= $day->format('j') ?></span><?php if($dayEvents): ?><span class="calendar-day-events"><?php foreach(array_slice($dayEvents,0,2) as $event): ?><span class="calendar-event-chip <?= (int)$event['concluido']?'event-done':'' ?>"><i></i><?= escape($event['titulo']) ?></span><?php endforeach; ?><?php if(count($dayEvents)>2): ?><small>+<?= count($dayEvents)-2 ?></small><?php endif; ?></span><?php endif; ?></a><?php endfor; ?></div><footer class="calendar-legend"><span><i></i> Sessão planejada</span><span><i class="legend-complete"></i> Concluída</span><span><b></b> Hoje</span></footer></section>
